  # independent expected based state/event
  kind=e['kind']; lanes=tuple(e['lanes']); sem=tuple(e['semantic'])
  inv={lane:t for t,lane in st.items()}
  if kind=='WAIT': exp=()
  elif kind=='SWAP':
   x,y=lanes; exp=tuple((inv[z], y if z==x else x) for z in (x,y) if z in inv)
  elif kind=='DUPLICATE':
   src,new,x,y=sem; exp=((new,y),)
  elif kind=='NAND':
   l,r,o,x,y=sem; exp=((l,None),(r,None),(o,x))
  assert d==exp,(e,d,exp)
  for t,lane in d:
   if lane is None: del st[t]
   else: st[t]=lane
 assert st==dict(c['final_token_map'])

